  id="step-4-register-in-the-starter-code-5"
  bind:intersecting={visibleById["step-4-register-in-the-starter-code-5"]}
  onIntersectChange={(visible) => setVisible("step-4-register-in-the-starter-code-5", visible)}
>Step 4: Register in the Starter Code</SectionComponent>
<p>Finally, register your external component so Freon can instantiate it.<br>
Open <code>externals.ts</code>, import your component, and add it to the <code>setCustomComponents</code> call:</p>
<pre class="language-ts"><code class="language-ts">// CourseSchedule/phase2/src/external/externals.ts

import &#123;setCustomComponents&#125; from "@freon4dsl/core-svelte";
import PersonIcon from "./PersonIcon.svelte";

/**
 * Configure the external components used, so Freon can find them.
 */
export function configureExternals() &#123;
    setCustomComponents([
        &#123; component: PersonIcon, knownAs: "PersonIcon" &#125;,
    ]);
&#125;
</code></pre>
